pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialDeposits, uint256 extraDeposits) public {
        // Keep initialDeposits bounded so the setup loop is feasible, but let the fuzzer choose the starting count.
        initialDeposits = bound(initialDeposits, 0, type(uint256).max - 1);
        vm.deal(address(this), initialDeposits + extraDeposits);
        // Perform initialDeposits deposits as the owner (any caller is allowed, but we need ether).
        for (uint256 i = 0; i < initialDeposits && i < 10_000; i++) {
            (bool ok, ) = address(c).call{value: 1}("");
            require(ok, "initial deposit failed");
        }
        uint256 depositsBefore = c.depositsCount();
        // Now perform extraDeposits deposits; the fuzzer may drive extraDeposits large enough to cause overflow.
        // In the reference version the overflow is prevented by the require; in the buggy version depositsCount wraps around.
        uint256 succeeded = 0;
        for (uint256 j = 0; j < extraDeposits && j < 10_000; j++) {
            (bool ok, ) = address(c).call{value: 1}("");
            if (ok) succeeded++;
        }
        uint256 depositsAfter = c.depositsCount();
        // Invariant: depositsCount is non-decreasing (it only increases or stays the same on revert).
        // The buggy version violates this when depositsCount wraps around to 0.
        assertTrue(depositsAfter >= depositsBefore);
    }
}

