pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 preDeposits) public {
        // Ensure pre-state is not already at max
        vm.assume(preDeposits < type(uint256).max);
        // Force the internal state using assembly (only allowed way to set depositsCount directly)
        // We use vm.store to set depositsCount to preDeposits, but vm.store is not allowed.
        // Instead, we will make preDeposits calls to receive with minimal value.
        // We need to avoid running out of gas, so we loop only if reasonable.
        // But looping up to type(uint256).max is impossible. Instead, we rely on a helper approach:
        // We cannot set the state directly without vm.store, so we must simplify:
        // Actually, we just need a valid deposit that may overflow; we fuzz only one call.
        // To expose the difference: after a single receive, depositsCount must be > oldCount OR the call reverts.
        uint256 oldCount = c.depositsCount();

        // Deal ether to make the call succeed if it doesn't revert
        vm.deal(address(this), amount);

        // Perform the receive call and catch revert
        bool ok;
        try c.receive{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 newCount = c.depositsCount();

        if (ok) {
            // If it succeeded, depositsCount must have increased by exactly 1 (reference never wraps)
            assertEq(newCount, oldCount + 1);
        } else {
            // If it reverted, oldCount must have been type(uint256).max (overflow case)
            assertEq(oldCount, type(uint256).max);
        }
    }
}

