pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 pre) public {
        // Pre-state: set depositsCount to `pre` via repeated deposits, but cap to a feasible number to keep runtime reasonable.
        // Bound to avoid excessive loops; still wide enough to include the overflow trigger.
        pre = bound(pre, 0, 256);
        for (uint256 i = 0; i < pre; i++) {
            vm.deal(address(this), 1 ether);
            (bool ok,) = address(c).call{value: 1}("");
            // Stop if a deposit fails (e.g., overflow in reference) because we cannot force beyond that.
            if (!ok) break;
        }

        uint256 beforeCount = c.depositsCount();
        uint256 snapshot = vm.snapshot();

        // Now attempt a single deposit with the fuzzer providing the amount (any value > 0).
        uint256 amount = 1; // Always 1 wei, the fuzzer searches by varying `pre`.
        vm.deal(address(this), amount);
        (bool success,) = address(c).call{value: amount}("");

        uint256 afterCount = c.depositsCount();
        if (success) {
            // If the deposit succeeded, the count must have increased.
            assertTrue(afterCount > beforeCount);
        } else {
            // If it reverted, the count must remain unchanged.
            assertTrue(afterCount == beforeCount);
        }

        // Restore state for next fuzz iteration (optional but good practice).
        vm.revertTo(snapshot);
    }
}

