    function setUp() public { c = new C(); }

    function testFuzz_property(address nonOwner, uint256 seed) public {
        vm.assume(nonOwner != address(0) && nonOwner != address(c));
        // nonOwner must not be the owner
        vm.assume(nonOwner != c.owner());

        // Fund the contract with a fuzzed amount between 1 wei and 100 ETH
        uint256 balance = (seed % 100 ether) + 1 wei;
        vm.deal(address(c), balance);

