        // Rule: After a call by a non-owner, the contract's ETH balance remains unchanged.
        // Reference: call reverts, balance unchanged. Mutant: call succeeds, balance decreases.
        uint256 afterBal = address(c).balance;
        assertTrue(ok ? (afterBal == beforeBal) : true, "Non-owner should not change balance");
    }
}

